#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define HEADER_MAX 64
#define BODY_MAX 512
#define PACKET_BUF_SIZE 576  /* HEADER_MAX + BODY_MAX */

typedef struct {
    uint8_t  version;
    uint8_t  msg_type;
    uint16_t header_len;
    uint16_t body_len;
    uint16_t checksum;
} __attribute__((packed)) wire_header_t;

typedef struct {
    char buffer[PACKET_BUF_SIZE];
    size_t write_pos;
    size_t capacity;
} packet_builder_t;

static uint16_t compute_checksum(const char *data, size_t len) {
    uint16_t sum = 0;
    for (size_t i = 0; i < len; i++) {
        sum = (sum << 1) ^ (uint8_t)data[i];
    }
    return sum;
}

static int validate_field_name(const char *name) {
    /* Only allow alphanumeric and underscore */
    for (int i = 0; name[i]; i++) {
        char c = name[i];
        if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
              (c >= '0' && c <= '9') || c == '_'))
            return 0;
    }
    return 1;
}

/* Append a TLV (tag-length-value) header field to the packet */
static int append_header_field(packet_builder_t *pkt, uint8_t tag,
                               const char *value, size_t value_len) {
    /* Each field: 1 byte tag + 1 byte length + value */
    size_t field_size = 2 + value_len;

    /* Bounds check: ensure we don't exceed header area */
    size_t remaining = pkt->capacity - pkt->write_pos;
    if (field_size > remaining) {
        return -1;
    }

    /* Also ensure we stay within HEADER_MAX region */
    if (pkt->write_pos + field_size > HEADER_MAX) {
        return -1;
    }

    pkt->buffer[pkt->write_pos++] = (char)tag;
    pkt->buffer[pkt->write_pos++] = (char)value_len;
    memcpy(&pkt->buffer[pkt->write_pos], value, value_len);
    pkt->write_pos += value_len;
    return 0;
}

/* Write body content with encoding - handles escape sequences */
static int write_body(packet_builder_t *pkt, const char *data, size_t data_len) {
    /* Body starts after HEADER_MAX offset */
    size_t body_start = HEADER_MAX;
    size_t body_pos = 0;

    for (size_t i = 0; i < data_len; i++) {
        size_t remaining_body = BODY_MAX - body_pos;

        if (data[i] == '\\' && i + 1 < data_len) {
            /* Escape sequence: \n, \t, \x## */
            if (data[i+1] == 'x' && i + 3 < data_len) {
                /* Hex escape: consume 4 chars, write 1 byte */
                if (remaining_body < 1) return -1;
                char hex[3] = {data[i+2], data[i+3], 0};
                pkt->buffer[body_start + body_pos] = (char)strtol(hex, NULL, 16);
                body_pos++;
                i += 3; /* skip \xHH */
            } else if (data[i+1] == 'n') {
                if (remaining_body < 1) return -1;
                pkt->buffer[body_start + body_pos] = '\n';
                body_pos++;
                i++;
            } else if (data[i+1] == 't') {
                if (remaining_body < 1) return -1;
                pkt->buffer[body_start + body_pos] = '\t';
                body_pos++;
                i++;
            } else {
                if (remaining_body < 1) return -1;
                pkt->buffer[body_start + body_pos] = data[i+1];
                body_pos++;
                i++;
            }
        } else {
            if (remaining_body < 1) return -1;
            pkt->buffer[body_start + body_pos] = data[i];
            body_pos++;
        }
    }

    /* Update write_pos to reflect total packet size */
    pkt->write_pos = body_start + body_pos;
    return (int)body_pos;
}

/* Finalize packet: write wire header at offset 0 */
static int finalize_packet(packet_builder_t *pkt, uint8_t version,
                           uint8_t msg_type, size_t header_data_len,
                           size_t body_len, char *out, size_t out_size) {
    wire_header_t hdr;
    hdr.version = version;
    hdr.msg_type = msg_type;
    hdr.header_len = (uint16_t)header_data_len;
    hdr.body_len = (uint16_t)body_len;

    size_t total_len = sizeof(wire_header_t) + header_data_len + body_len;
    if (total_len > out_size) {
        return -1;
    }

    /* Compute checksum over header fields + body */
    hdr.checksum = compute_checksum(pkt->buffer + sizeof(wire_header_t),
                                    header_data_len + body_len);

    /* Assemble final packet */
    memcpy(out, &hdr, sizeof(wire_header_t));
    memcpy(out + sizeof(wire_header_t), pkt->buffer + sizeof(wire_header_t),
           header_data_len);
    memcpy(out + sizeof(wire_header_t) + header_data_len,
           pkt->buffer + HEADER_MAX, body_len);

    return (int)total_len;
}

/*
 * Process an incoming message request.
 * Fields: name=value pairs separated by '|'
 * Body follows after '\n\n'
 */
int process_message(const char *input, size_t input_len,
                    char *output, size_t output_size) {
    packet_builder_t pkt;
    memset(&pkt, 0, sizeof(pkt));
    pkt.capacity = PACKET_BUF_SIZE;
    pkt.write_pos = sizeof(wire_header_t); /* Reserve space for wire header */

    /* Find header/body separator */
    const char *body_sep = NULL;
    for (size_t i = 0; i + 1 < input_len; i++) {
        if (input[i] == '\n' && input[i+1] == '\n') {
            body_sep = &input[i+2];
            break;
        }
    }

    size_t header_section_len = body_sep ? (size_t)(body_sep - input) - 2 : input_len;

    /* Parse header fields */
    const char *pos = input;
    const char *header_end = input + header_section_len;
    uint8_t tag_counter = 1;
    size_t header_data_written = 0;

    while (pos < header_end) {
        /* Find next '|' or end */
        const char *delim = memchr(pos, '|', (size_t)(header_end - pos));
        size_t field_len = delim ? (size_t)(delim - pos) : (size_t)(header_end - pos);

        /* Find '=' separator */
        const char *eq = memchr(pos, '=', field_len);
        if (!eq) {
            pos += field_len + 1;
            continue;
        }

        size_t name_len = (size_t)(eq - pos);
        size_t val_len = field_len - name_len - 1;

        /* Validate field name */
        char name_buf[32];
        if (name_len >= sizeof(name_buf)) {
            pos += field_len + 1;
            continue;
        }
        memcpy(name_buf, pos, name_len);
        name_buf[name_len] = '\0';

        if (!validate_field_name(name_buf)) {
            pos += field_len + 1;
            continue;
        }

        /* Value length check */
        if (val_len > 60) {
            val_len = 60; /* Truncate long values */
        }

        size_t before = pkt.write_pos;
        if (append_header_field(&pkt, tag_counter++, eq + 1, val_len) != 0) {
            break;
        }
        header_data_written += pkt.write_pos - before;

        pos += field_len + 1;
    }

    /* Process body if present */
    size_t body_written = 0;
    if (body_sep) {
        size_t body_input_len = input_len - (size_t)(body_sep - input);
        int bw = write_body(&pkt, body_sep, body_input_len);
        if (bw < 0) return -1;
        body_written = (size_t)bw;
    }

    return finalize_packet(&pkt, 1, 0x10, header_data_written,
                           body_written, output, output_size);
}

/* Multi-packet aggregation: combine multiple messages */
int aggregate_packets(const char **messages, size_t *msg_lens,
                      int msg_count, char *output, size_t output_size) {
    size_t total_written = 0;

    for (int i = 0; i < msg_count && i < 16; i++) {
        size_t space_left = output_size - total_written;

        int pkt_len = process_message(messages[i], msg_lens[i],
                                      output + total_written, space_left);
        if (pkt_len < 0) {
            continue; /* Skip malformed messages */
        }
        total_written += (size_t)pkt_len;
    }

    return (int)total_written;
}

/* Packet reassembly from fragmented stream */
typedef struct {
    char reassembly_buf[4096];
    size_t buf_used;
    int fragments_received;
} reassembly_ctx_t;

int receive_fragment(reassembly_ctx_t *ctx, const char *frag_data,
                     uint16_t frag_len, uint16_t frag_offset,
                     uint16_t total_len) {
    /* Validate total length */
    if (total_len > sizeof(ctx->reassembly_buf)) {
        return -1;
    }

    /* Validate fragment bounds - use size_t to prevent uint16 wraparound */
    size_t end_offset = (size_t)frag_offset + (size_t)frag_len;
    if (end_offset > (size_t)total_len) {
        return -1;
    }

    /* Safe: end_offset <= total_len <= sizeof(reassembly_buf) */
    memcpy(ctx->reassembly_buf + frag_offset, frag_data, frag_len);
    ctx->buf_used = (end_offset > ctx->buf_used) ? end_offset : ctx->buf_used;
    ctx->fragments_received++;

    return 0;
}

int complete_reassembly(reassembly_ctx_t *ctx, char *output,
                        size_t output_size, uint16_t expected_total) {
    if (ctx->buf_used < expected_total) {
        return -1; /* Incomplete */
    }
    size_t copy_len = expected_total < output_size ? expected_total : output_size;
    memcpy(output, ctx->reassembly_buf, copy_len);
    return (int)copy_len;
}
